using Kingmaker.Blueprints;
using Kingmaker.Blueprints.Classes;
using Kingmaker.Blueprints.Classes.Prerequisites;
using Kingmaker.Blueprints.Classes.Selection;
using IsekaiMod.Utilities;
using TabletopTweaks.Core.Utilities;
int checks = 0;
void Check(bool condition, string label) { if (!condition) throw new Exception(label); checks++; Console.WriteLine("PASS " + label); }
BlueprintFeature F(string id) => new() { AssetGuid = id, name = id };
var source = F("source"); var equivalent = F("equivalent"); var other = F("other"); var target = F("target");
var required = new PrerequisiteFeature { m_Feature = source.ToReference<BlueprintFeatureReference>(), Group = Prerequisite.GroupType.All, CheckInProgression = true, HideInUI = true };
var unrelated = new PrerequisiteFeature { m_Feature = other.ToReference<BlueprintFeatureReference>(), Group = Prerequisite.GroupType.All };
target.ComponentsArray = [required, unrelated];
Check(PrerequisiteAlternatives.Add(target, source, equivalent), "accepts wrapper alternative");
var list = target.GetComponents<PrerequisiteFeaturesFromList>().Single();
Check(list.Group == Prerequisite.GroupType.All && list.Amount == 1 && list.CheckInProgression && list.HideInUI, "preserves requirement group and flags");
Check(target.ComponentsArray.Contains(unrelated), "preserves unrelated prerequisite");
bool Eligible(params string[] facts) => target.GetComponents<Prerequisite>().Where(p => p.Group == Prerequisite.GroupType.All).All(p => p switch { PrerequisiteFeature f => facts.Contains(f.Feature.AssetGuid), PrerequisiteFeaturesFromList l => l.m_Features.Count(f => facts.Contains(f.Guid)) >= l.Amount, _ => true });
Check(!Eligible("equivalent"), "wrapper alone does not bypass unrelated requirement");
Check(Eligible("equivalent", "other"), "wrapper plus other requirement qualifies");
Check(Eligible("source", "other"), "vanilla qualification remains valid");
Check(!PrerequisiteAlternatives.Add(target, source, equivalent) && list.m_Features.Length == 2, "repeated refresh is idempotent");
var second = F("second"); PrerequisiteAlternatives.Add(target, source, second);
Check(list.m_Features.Length == 3 && Eligible("second", "other"), "supports multiple equivalent wrappers");
var unknown = F("unknown"); Check(!PrerequisiteAlternatives.Add(unknown, source, equivalent) && unknown.ComponentsArray.Length == 0, "missing source requirement is unchanged");
var multi = F("multi"); var multiReq = new PrerequisiteFeaturesFromList { Amount = 2, m_Features = [source.ToReference<BlueprintFeatureReference>(), other.ToReference<BlueprintFeatureReference>()] }; multi.ComponentsArray = [multiReq];
Check(!PrerequisiteAlternatives.Add(multi, source, equivalent) && multiReq.m_Features.Length == 2, "does not double-count source and wrapper in multi-fact requirements");
var any = F("any"); any.ComponentsArray = [new PrerequisiteFeature { m_Feature = source.ToReference<BlueprintFeatureReference>(), Group = Prerequisite.GroupType.Any }]; PrerequisiteAlternatives.Add(any, source, equivalent);
Check(any.GetComponents<PrerequisiteFeaturesFromList>().Single().Group == Prerequisite.GroupType.Any, "preserves existing Any group");
Check(!PrerequisiteAlternatives.Add(null, source, equivalent), "null target is harmless");
var selection = new BlueprintFeatureSelection { m_AllFeatures = [source.ToReference<BlueprintFeatureReference>(), null, source.ToReference<BlueprintFeatureReference>()] };
PrerequisiteAlternatives.RequireUnownedChoices(selection); PrerequisiteAlternatives.RequireUnownedChoices(selection);
Check(source.GetComponents<PrerequisiteNoFeature>().Count() == 1, "ownership guard is null-safe and idempotent");


var standardExceptional = new BlueprintFeatureSelection {name="ExceptionalFeatSelection",AssetGuid="exceptional-standard"};
var bonusExceptional = new BlueprintFeatureSelection {name="ExceptionalFeatBonusSelection",AssetGuid="exceptional-bonus"};
var basic = new BlueprintFeatureSelection { name="Basic", AssetGuid="basic", m_AllFeatures=[standardExceptional.ToReference<BlueprintFeatureReference>(),source.ToReference<BlueprintFeatureReference>()] };
var bonusMenu = new BlueprintFeatureSelection { name="IsekaiBonusFeatSelection", AssetGuid="bonus-menu", m_AllFeatures=[bonusExceptional.ToReference<BlueprintFeatureReference>(),source.ToReference<BlueprintFeatureReference>()] };
FeatTools.Selections.BasicFeatSelection=basic;
BlueprintTools.Blueprints[standardExceptional.name]=standardExceptional;
BonusFeatListRefresh.Snapshot(bonusMenu.name);
// A late mod adds a feat, while the current menu already contains both Exceptional wrappers.
basic.m_AllFeatures=[..basic.m_AllFeatures, other.ToReference<BlueprintFeatureReference>()];
bonusMenu.m_AllFeatures=[..bonusMenu.m_AllFeatures,standardExceptional.ToReference<BlueprintFeatureReference>()];
BonusFeatListRefresh.Refresh(bonusMenu);
Check(bonusMenu.m_AllFeatures.Select(f=>f.Guid).SequenceEqual(new[]{"exceptional-bonus","source","other"}), "refresh removes standard wrapper but preserves bonus wrapper and late feats");
BonusFeatListRefresh.Refresh(bonusMenu);
Check(bonusMenu.m_AllFeatures.Length==3 && bonusMenu.m_Features.Select(f=>f.Guid).SequenceEqual(bonusMenu.m_AllFeatures.Select(f=>f.Guid)), "repeated refresh keeps both menu arrays consistent without duplicates");
Check(basic.m_AllFeatures.Any(f=>f.Guid=="exceptional-standard"), "standard feat menu retains its Exceptional choice");
var solo=new BlueprintFeatureSelection {name="SoloSovereignFeatSelection",m_AllFeatures=basic.m_AllFeatures};
BonusFeatListRefresh.Snapshot(solo.name);BonusFeatListRefresh.Refresh(solo);
Check(solo.m_AllFeatures.Any(f=>f.Guid=="exceptional-standard"), "Solo Sovereign retains the standard wrapper");
Console.WriteLine($"{checks} behavior checks passed. Uses API stubs; does not simulate the game runtime.");
